export const guides=[
{
file:'brazil-pvc-wall-panels-portuguese-installation-pack.html',image:'brazil-pvc-handover-20261021.webp',product:'/products/pvc-wall-panels.html',catalog:'/assets/catalogs/3d-pvc-panel-catalog.pdf',source:'https://www.dumaplast.com/en/frequently-asked-questions/pvc-panels-silicon',sourceName:'Dumaplast: product-specific joint sealing guidance',related:['brazil-pvc-ceiling-panel-import-documents.html','wall-panel-trims-accessories-guide.html'],
en:{title:'Brazil PVC Panels: Portuguese Installation Pack | Luvie',heading:'PVC wall panels for Brazil: prepare a Portuguese installation pack',description:'Prepare Portuguese installation documents for Brazilian PVC panel distributors: match product codes, clarify joint details and verify the installer handover.',lead:'A Brazilian distributor may receive the right PVC wall panels but still lose time answering the same installer questions. A catalog shows finishes; it does not necessarily explain how a particular panel meets a corner, an opening or a wet-area junction. Before printing a Portuguese leaflet, build a controlled handover pack for the exact product being ordered. This is a practical documentation workflow, not a statement of Brazilian regulatory compliance.',answer:'Keep the approved product code, current installation instructions, accessory schedule and Portuguese terminology together. Have the supplier confirm technical meaning and a local installer check whether the instructions can actually be followed.',sections:[
['Separate the catalog from installation instructions','Start with a document register: product reference, supplier instruction revision, Portuguese revision, approval date and responsible reviewer. Identify whether the order is for wall or ceiling use and which applications remain unapproved. A photograph of a similar profile is not a substitute for the ordered drawing. If instructions are missing, request them before translating; do not fill the gap with another manufacturer’s fixing spacing or adhesive recommendation.'],
['Translate the decisions, not only the headings','Agree terms such as largura útil, perfil de acabamento and junta de dilatação with the Brazilian installation team. Show dimensions in clearly identified units, explain coverage separately from overall panel width and preserve every qualification in the original instructions. Include a labeled sketch of the actual trim assembly. Where a supplier drawing is unclear, send a question back instead of letting the translator invent a construction detail.'],
['Make water-related limitations visible','The linked Dumaplast guidance discusses sealing joints for its own wet-room installations. It illustrates why panel material and installed joints are separate questions; it does not approve a Luvie system. Ask for the ordered panel’s permitted locations, substrate preparation, compatible joint products and treatment around penetrations. Do not turn a general waterproof headline into permission for every shower assembly. Have the project team resolve missing wet-area details before purchase.'],
['Trial the pack before releasing it to dealers','Give the pack and a small mockup kit to an installer who did not write it. Ask them to identify the first panel, finishing trim, restrictions and whom to contact when the wall differs from the drawing. Record unanswered questions and revise the pack. Put a revision identifier on the PDF and printed sheet; keep a stable download link and withdraw superseded copies. For each shipment, record which revision accompanied the product.']
],checklist:['Exact panel reference and approved application','Supplier instructions and Portuguese revision register','Matched trims and unresolved technical questions','Installer trial and controlled download link'],faq:[['Can the product catalog serve as the installation manual?','Only if it actually contains the approved instructions for that exact system. A finish catalog alone is insufficient.'],['Must the original product PDF be rewritten?','No. Keep it unchanged and supply a separate Portuguese introduction and approved installation pack.']],closing:'Send Luvie the selected PVC reference, Brazilian sales channel and installation questions. Request the applicable technical documents before finalizing translated customer instructions.'},
es:{title:'Brasil: instrucciones de paneles PVC en portugués | Luvie',heading:'Paneles PVC para Brasil: preparar instrucciones en portugués',description:'Organice la entrega técnica de paneles PVC a distribuidores brasileños: referencias, revisiones, accesorios y comprobación con el instalador local.',lead:'Un distribuidor brasileño puede recibir los paneles correctos y aun así dedicar tiempo a resolver las mismas dudas de instalación. El catálogo muestra acabados, pero no siempre explica esquinas, huecos o encuentros húmedos. Antes de imprimir una hoja en portugués, prepare un paquete documental para el producto exacto. Es un método de trabajo, no una declaración de cumplimiento normativo brasileño.',answer:'Reúna código aprobado, instrucciones vigentes, lista de accesorios y terminología portuguesa. El proveedor debe confirmar el sentido técnico y un instalador local comprobar que puede aplicar las instrucciones.',sections:[
['Separe catálogo e instrucciones','Cree un registro con referencia, revisión del proveedor, revisión portuguesa, fecha y responsable. Distinga uso en pared o techo y aplicaciones no aprobadas. Una foto de un perfil parecido no sustituye al plano del pedido. Si faltan instrucciones, solicítelas antes de traducir: no copie distancias de fijación ni adhesivos de otra marca.'],
['Traduzca las decisiones técnicas','Acuerde términos como largura útil, perfil de acabamento y junta de dilatação con el equipo brasileño. Indique unidades y diferencie cobertura de anchura total. Mantenga todas las condiciones del original e incluya un dibujo identificado del accesorio real. Si el plano es ambiguo, pregunte al proveedor; el traductor no debe inventar la solución constructiva.'],
['Haga visibles las limitaciones frente al agua','La referencia de Dumaplast trata el sellado en sus propias instalaciones húmedas. Demuestra que material y juntas son cuestiones distintas; no aprueba un sistema Luvie. Solicite usos permitidos, preparación del soporte, productos compatibles y detalles de penetraciones del panel elegido. Una afirmación general de impermeabilidad no autoriza cualquier ducha. El equipo del proyecto debe resolver los puntos pendientes antes de comprar.'],
['Pruebe el paquete antes de distribuirlo','Entregue documentos y una pequeña maqueta a un instalador ajeno a la redacción. Pídale identificar primera pieza, remate, restricciones y contacto cuando la pared no coincida con el plano. Registre dudas y corrija. Identifique la revisión en PDF y papel, mantenga un enlace estable y retire versiones antiguas. Anote qué revisión acompaña cada envío.']
],checklist:['Referencia exacta y aplicación aprobada','Instrucciones originales y registro de traducción','Accesorios compatibles y dudas pendientes','Prueba con instalador y enlace controlado'],faq:[['¿El catálogo sustituye al manual?','Solo si contiene las instrucciones aprobadas del sistema exacto; un catálogo de acabados no basta.'],['¿Hay que modificar el PDF original?','No. Puede mantenerse y acompañarse de una introducción portuguesa y documentación aprobada separada.']],closing:'Envíe a Luvie la referencia PVC, el canal brasileño y las dudas de montaje. Pida documentación aplicable antes de cerrar las instrucciones traducidas.'},
'pt-br':{title:'Painéis PVC no Brasil: documentação de instalação | Luvie',heading:'Painéis de PVC para o Brasil: prepare o pacote de instalação em português',description:'Organize instruções em português para distribuidores de painéis PVC: códigos, revisões, acessórios, detalhes de juntas e validação com o instalador.',lead:'Um distribuidor brasileiro pode receber os painéis corretos e ainda perder tempo respondendo às mesmas dúvidas de instalação. O catálogo apresenta acabamentos, mas nem sempre explica cantos, aberturas ou encontros em áreas molhadas. Antes de imprimir um folheto, prepare a documentação do produto exato. Este é um fluxo de trabalho prático, não uma declaração de conformidade regulatória brasileira.',answer:'Reúna código aprovado, instruções vigentes, relação de acessórios e terminologia em português. O fornecedor confirma o significado técnico; um instalador local verifica se as orientações são executáveis.',sections:[
['Separe catálogo e manual de instalação','Monte um registro com referência do produto, revisão do fornecedor, revisão em português, data e responsável. Diferencie aplicação em parede e teto e indique usos ainda não aprovados. A foto de um perfil semelhante não substitui o desenho do pedido. Solicite instruções ausentes antes de traduzir; não preencha lacunas copiando espaçamento de fixação ou adesivo de outro fabricante.'],
['Traduza as decisões, não apenas os títulos','Alinhe termos como largura útil, perfil de acabamento e junta de dilatação com a equipe de instalação. Identifique as unidades, diferencie cobertura e largura total e preserve todas as condições do original. Inclua um desenho identificado do conjunto de acabamento real. Quando houver ambiguidade, consulte o fornecedor em vez de deixar o tradutor inventar um detalhe construtivo.'],
['Destaque as limitações relacionadas à água','A orientação da Dumaplast aborda vedação nas instalações úmidas dos próprios produtos. Ela mostra que material e juntas instaladas são questões diferentes; não aprova um sistema Luvie. Peça usos permitidos, preparo da base, produtos compatíveis e tratamento de passagens para o painel escolhido. Não transforme uma chamada genérica de impermeabilidade em autorização para qualquer box. Resolva detalhes pendentes com a equipe do projeto antes da compra.'],
['Teste os documentos antes de entregar às lojas','Forneça o pacote e uma pequena montagem de teste a um instalador que não participou da redação. Peça que identifique primeira peça, acabamento, restrições e contato para quando a parede divergir do desenho. Registre dúvidas e revise. Marque a revisão no PDF e no impresso, mantenha um link estável e retire cópias antigas. Registre qual versão acompanhou cada remessa.']
],checklist:['Referência exata e aplicação aprovada','Instruções do fornecedor e controle de revisão','Acabamentos compatíveis e questões pendentes','Teste com instalador e link controlado'],faq:[['O catálogo pode substituir o manual?','Somente se contiver as instruções aprovadas para aquele sistema. Um catálogo de acabamentos não basta.'],['É necessário reescrever o PDF original?','Não. Preserve o original e entregue uma introdução em português e documentos de instalação aprovados separadamente.']],closing:'Envie à Luvie a referência PVC, o canal de venda brasileiro e as dúvidas de instalação. Solicite os documentos aplicáveis antes de finalizar as instruções ao cliente.'},
ar:{title:'ألواح PVC للبرازيل: ملف التركيب البرتغالي | Luvie',heading:'ألواح PVC للبرازيل: إعداد ملف تركيب باللغة البرتغالية',description:'نظم تسليم مستندات تركيب ألواح PVC للموزع البرازيلي، مع مراجعات واضحة وأكواد المنتجات والملحقات وتجربة عملية لدى فريق التركيب.',lead:'قد يستلم الموزع البرازيلي الألواح الصحيحة، ثم يقضي وقتاً في الإجابة عن أسئلة تركيب متكررة. يعرض الكتالوج التشطيبات لكنه لا يوضح دائماً الزوايا والفتحات والوصلات في الأماكن الرطبة. قبل طباعة نشرة برتغالية، جهز ملفاً للمنتج المحدد في الطلب. هذا إجراء لتنظيم العمل وليس إقراراً بالامتثال للأنظمة البرازيلية.',answer:'اجمع كود المنتج المعتمد وتعليمات التركيب الحالية وقائمة الملحقات والمصطلحات البرتغالية. يؤكد المورد المعنى الفني، ويتحقق مركب محلي من إمكانية تطبيق التعليمات.',sections:[
['افصل الكتالوج عن تعليمات التركيب','أنشئ سجلاً يتضمن مرجع المنتج وإصدار المورد والإصدار البرتغالي وتاريخ الاعتماد والمسؤول. ميز بين استخدام الجدار والسقف والتطبيقات غير المعتمدة. صورة مقطع مشابه لا تعوض رسم المنتج المطلوب. اطلب التعليمات الناقصة قبل الترجمة؛ لا تستعر مسافات التثبيت أو توصية اللاصق من مصنع آخر لسد الفراغ.'],
['ترجم القرارات الفنية لا العناوين فقط','اتفق مع الفريق البرازيلي على مصطلحات مثل largura útil وperfil de acabamento وjunta de dilatação. وضح الوحدات وافصل مساحة التغطية عن العرض الكلي وحافظ على شروط النص الأصلي. أرفق رسماً معرفاً للملحق الفعلي. إذا كان الرسم غامضاً، أعد السؤال إلى المورد بدلاً من ترك المترجم يبتكر تفصيلاً إنشائياً.'],
['أظهر القيود المتعلقة بالماء','يتناول مرجع Dumaplast سد الوصلات في تطبيقاته الرطبة الخاصة. وهو يوضح اختلاف مادة اللوح عن الوصلة المركبة، ولا يعتمد نظام Luvie. اطلب الأماكن المسموح بها وتحضير السطح ومواد الوصل المتوافقة وتفاصيل الاختراقات للمنتج المختار. لا تحول وصفاً عاماً لمقاومة الماء إلى موافقة لكل نظام دش. يجب حسم التفاصيل المفقودة مع فريق المشروع قبل الشراء.'],
['جرب الملف قبل توزيعه على التجار','قدم المستندات ومجموعة تركيب صغيرة إلى مركب لم يشارك في إعدادها. اطلب تحديد اللوح الأول والحلية والقيود وجهة الاتصال عندما يختلف الجدار عن الرسم. سجل الأسئلة وعدل الملف. ضع رقم الإصدار على النسخة الرقمية والمطبوعة، وحافظ على رابط ثابت واسحب النسخ القديمة. سجل الإصدار الذي رافق كل شحنة.']
],checklist:['مرجع اللوح وتطبيقه المعتمد','تعليمات المورد وسجل النسخ المترجمة','ملحقات متوافقة وأسئلة فنية معلقة','تجربة مركب ورابط تنزيل مضبوط'],faq:[['هل يغني الكتالوج عن دليل التركيب؟','فقط إذا احتوى التعليمات المعتمدة للنظام نفسه. كتالوج التشطيبات وحده غير كاف.'],['هل يجب تعديل ملف PDF الأصلي؟','لا. يمكن إبقاؤه وإرفاق مقدمة برتغالية وملف تركيب معتمد منفصل.']],closing:'أرسل إلى Luvie مرجع PVC وقناة البيع البرازيلية وأسئلة التركيب. اطلب المستندات المناسبة قبل اعتماد تعليمات العميل المترجمة.'}
},
{
file:'iraq-wpc-shop-interiors-maintenance-spares.html',image:'iraq-wpc-spares-20261021.webp',product:'/products/wpc-wall-panels.html',catalog:'/assets/catalogs/wpc-collection-2026.pdf',source:'https://www.newtechwood.com/composite-siding-installation/',sourceName:'NewTechWood: system-specific composite installation details',related:['wall-panel-trims-accessories-guide.html','reduce-wall-panel-batch-color-differences.html'],
en:{title:'Iraq WPC Shop Interiors: Plan Maintenance Spares | Luvie',heading:'WPC wall panels for Iraqi shop interiors: what spare materials should you order?',description:'Plan WPC spare panels and trims for Iraqi shop fit-outs: distinguish cutting waste from maintenance stock, test replacement access and record stored materials.',lead:'Imagine an Iraqi shop reopening after a fit-out, then discovering that one damaged fluted panel cannot be replaced without disturbing the adjacent trim. This is a planning scenario, not a reported Luvie project. The useful procurement question is not simply how many extra square metres to buy. It is which full pieces, accessories and records will make a later repair possible without another complete order.',answer:'Separate installation allowance from owner-held maintenance stock. Choose spares from the approved assembly and replacement method, retain matching accessories, and document who stores and releases them. Do not assume one percentage suits every shop.',sections:[
['Divide the order into three quantities','List net installed material, estimated cutting allowance and separately identified maintenance spares. Have the installer calculate cuts from elevations rather than a blanket uplift. For a Baghdad or Erbil project, record the actual receiving location and storage custodian instead of relying on the destination city alone. Ask the supplier whether spare pieces can come from the same production lot, without treating that as an automatic color-match guarantee.'],
['Specify a repairable assembly before buying extras','Ask the installer to explain how a panel in the middle of the wall would be removed and replaced. Concealed fixings, adhesive and interlocking edges can change the answer. The linked NewTechWood exterior guidance illustrates that fixings and movement details are system-specific; its dimensions must not be transferred to interior Luvie panels. Obtain the selected product’s instructions and test a representative assembly before promising easy replacement.'],
['Reserve the small parts that stop a repair','Create a spare schedule by product code: full usable panel lengths, end pieces, corner profiles and the particular fasteners required by the approved design. Identify whether a removed trim can be reused. Avoid storing mixed unidentified offcuts as the only reserve. If a finish-matching accessory is unavailable, agree the alternative before installation. Keep cleaning or touch-up products only when specifically approved and within their usable storage life.'],
['Hand the reserve to the owner with a record','Label each bundle with product reference, lot if supplied, quantity, length and installation location. Store according to the manufacturer’s instructions away from damage and unsuitable exposure. Give the shop operator photographs and a stock list in a language their maintenance team can use, with Arabic text reviewed locally where required. Record withdrawals after repairs. A future order should reference the original specification and a retained sample, not just a color nickname.']
],checklist:['Separate net quantity, cutting allowance and reserve','Tested replacement method for the chosen assembly','Coded panels, trims and fixing list','Named custodian and maintenance stock record'],faq:[['Is ten percent spare stock always enough?','No. Wall geometry, available piece lengths and replacement access determine the reserve; agree it for the project.'],['Do spares make an indoor panel suitable outdoors?','No. Reserve planning does not change approved use or establish weather, fire or impact performance.']],closing:'Send Luvie the interior elevations, selected WPC profile and proposed repair method. Request panel and accessory availability for a separately identified maintenance reserve.'},
es:{title:'Irak: repuestos WPC para interiores comerciales | Luvie',heading:'Paneles WPC para tiendas en Irak: planificar repuestos de mantenimiento',description:'Separe recortes y repuestos en pedidos WPC para tiendas iraquíes. Revise acceso de sustitución, perfiles, fijaciones y registro de material reservado.',lead:'Imagine una tienda iraquí recién reformada donde un panel dañado no puede cambiarse sin desmontar el remate vecino. Es un supuesto de planificación, no un proyecto documentado de Luvie. La pregunta no es solo cuántos metros adicionales comprar, sino qué piezas y registros permitirán reparar sin repetir todo el pedido.',answer:'Separe merma de instalación y reserva del propietario. Elija repuestos según el sistema aprobado y el método de sustitución, conserve accesorios compatibles y asigne responsable. No aplique un porcentaje universal.',sections:[
['Divida el pedido en tres cantidades','Indique material neto instalado, recortes estimados y repuestos de mantenimiento identificados aparte. El instalador debe calcular cortes con los alzados, no con un incremento arbitrario. Para Bagdad o Erbil, registre dirección real de recepción y custodio. Consulte si los repuestos pueden proceder del mismo lote, sin interpretar esa posibilidad como garantía automática de igualdad de color.'],
['Compruebe la sustitución antes de comprar extras','Pida explicar cómo retirar un panel situado en medio del paño. Adhesivo, fijaciones ocultas y uniones cambian el procedimiento. La guía exterior de NewTechWood muestra que los detalles dependen del sistema; sus medidas no se trasladan a paneles interiores Luvie. Obtenga instrucciones del producto elegido y pruebe una maqueta antes de prometer sustitución sencilla.'],
['Reserve también las piezas pequeñas','Prepare una lista por código: paneles de longitud útil, terminaciones, esquinas y fijaciones del diseño aprobado. Confirme si el remate desmontado puede reutilizarse. No use recortes mezclados sin identificar como única reserva. Acuerde alternativas a accesorios faltantes antes del montaje. Guarde productos de retoque o limpieza únicamente si están aprobados y dentro de su vida útil de almacenamiento.'],
['Entregue la reserva con un registro','Etiquete referencia, lote disponible, cantidad, longitud y ubicación instalada. Almacene según instrucciones del fabricante y protegido de daños. Entregue fotografías y listado en un idioma útil para mantenimiento, con revisión local del árabe cuando corresponda. Registre cada retirada. Una reposición futura debe referirse a especificación y muestra conservada, no solo al nombre comercial del color.']
],checklist:['Cantidad neta, recortes y reserva separados','Método de sustitución probado','Lista codificada de paneles y accesorios','Custodio y registro de existencias'],faq:[['¿Siempre basta un diez por ciento?','No. Geometría, longitudes y acceso determinan la reserva del proyecto.'],['¿Los repuestos permiten usar el panel fuera?','No. No cambian su uso aprobado ni acreditan resistencia al clima, fuego o impactos.']],closing:'Envíe a Luvie alzados, perfil WPC y método de reparación previsto. Consulte disponibilidad de paneles y accesorios para una reserva separada.'},
'pt-br':{title:'Iraque: reserva de painéis WPC para lojas | Luvie',heading:'Painéis WPC em lojas no Iraque: quais peças reservar para manutenção?',description:'Planeje a reserva de painéis WPC e acabamentos para lojas iraquianas: perdas de corte, acesso para troca, códigos e controle do estoque de manutenção.',lead:'Imagine uma loja iraquiana recém-reformada em que um painel danificado não pode ser trocado sem desmontar o acabamento vizinho. É um cenário de planejamento, não um projeto real atribuído à Luvie. A questão não é apenas comprar metros extras, mas separar peças e registros que permitam reparar sem refazer o pedido completo.',answer:'Separe perdas de instalação e reserva de manutenção do proprietário. Escolha peças conforme o sistema aprovado e o procedimento de troca, inclua acessórios compatíveis e defina quem guarda e libera o material.',sections:[
['Divida o pedido em três quantidades','Liste material líquido instalado, perda estimada de corte e reserva identificada separadamente. Peça ao instalador calcular cortes pelos desenhos das paredes, não por um acréscimo genérico. Para Bagdá ou Erbil, registre endereço efetivo de recebimento e responsável pelo estoque. Consulte a possibilidade de peças do mesmo lote, sem interpretar isso como garantia automática de igualdade de cor.'],
['Valide a troca antes de comprar peças extras','Peça ao instalador explicar a retirada de um painel no centro da parede. Cola, fixações ocultas e encaixes alteram o procedimento. A orientação externa da NewTechWood mostra que os detalhes dependem do sistema; suas medidas não devem ser copiadas para painéis internos Luvie. Obtenha as instruções do produto escolhido e teste uma montagem antes de prometer substituição fácil.'],
['Inclua os pequenos componentes','Crie uma lista por código com comprimentos úteis de painel, terminais, cantoneiras e fixadores do projeto aprovado. Verifique se o acabamento removido é reutilizável. Não trate retalhos misturados e sem identificação como única reserva. Combine alternativas a acessórios indisponíveis antes da instalação. Armazene produtos de retoque ou limpeza apenas quando aprovados e dentro do prazo de uso em estoque.'],
['Entregue a reserva acompanhada de registro','Identifique referência, lote informado, quantidade, comprimento e local de instalação. Siga as instruções de armazenamento e proteja contra danos. Forneça fotos e inventário em idioma compreendido pela manutenção, com revisão local do árabe quando necessário. Registre retiradas após reparos. Um pedido futuro deve usar especificação e amostra guardada, não apenas um apelido de cor.']
],checklist:['Quantidade líquida, perdas e reserva separadas','Procedimento de troca testado','Lista codificada de painéis e acessórios','Responsável e registro do estoque'],faq:[['Dez por cento de reserva sempre basta?','Não. Geometria, comprimentos disponíveis e acesso para troca determinam a quantidade do projeto.'],['A reserva permite usar painel interno ao ar livre?','Não. Ela não altera uso aprovado nem comprova desempenho ao tempo, fogo ou impacto.']],closing:'Envie à Luvie os desenhos das paredes, o perfil WPC e o método de reparo previsto. Consulte disponibilidade de peças para uma reserva identificada à parte.'},
ar:{title:'العراق: قطع صيانة لألواح WPC داخل المحلات | Luvie',heading:'ألواح WPC لداخل المحلات العراقية: ما قطع الغيار التي ينبغي طلبها؟',description:'خطط لاحتياطي ألواح WPC وحلياتها في المحلات العراقية، وافصل هدر القص عن قطع الصيانة وتحقق من طريقة الاستبدال وسجل التخزين.',lead:'تخيل محلاً عراقياً بعد التجديد يتبين فيه أن استبدال لوح مخدد تالف يتطلب فك الحلية المجاورة. هذا مثال تخطيطي وليس مشروعاً موثقاً لشركة Luvie. السؤال المفيد ليس عدد الأمتار الإضافية فقط، بل القطع والسجلات اللازمة للإصلاح دون إعادة طلب كامل المواد.',answer:'افصل سماحيات التركيب عن احتياطي الصيانة لدى المالك. اختر القطع وفق النظام المعتمد وطريقة الاستبدال، وأضف الملحقات المتوافقة وحدد مسؤول التخزين والصرف. لا تفترض نسبة واحدة لكل المحلات.',sections:[
['قسم الطلب إلى ثلاث كميات','سجل صافي المواد المركبة وسماحية القص المقدرة واحتياطي الصيانة بشكل مستقل. احسب القص من مخططات الجدران مع المركب بدلاً من زيادة عامة. لمشروع في بغداد أو أربيل، حدد عنوان الاستلام الفعلي وأمين المخزن، لا اسم المدينة فقط. اسأل عن إمكانية توريد الاحتياطي من الدفعة نفسها دون اعتبار ذلك ضماناً تلقائياً لتطابق اللون.'],
['تحقق من إمكانية الإصلاح قبل شراء الزيادة','اطلب شرح كيفية فك لوح وسط الجدار واستبداله. تختلف الإجابة باختلاف اللاصق والتثبيت المخفي والحواف المتشابكة. يوضح دليل NewTechWood الخارجي أن تفاصيل التركيب مرتبطة بالنظام؛ لا تنقل أبعاده إلى ألواح Luvie الداخلية. احصل على تعليمات المنتج المختار وجرب نموذجاً قبل التعهد بسهولة الاستبدال.'],
['احتفظ بالملحقات الصغيرة اللازمة للإصلاح','أعد قائمة بالأكواد تشمل أطوال الألواح الصالحة والحليات النهائية والزوايا والمثبتات المحددة في التصميم المعتمد. تحقق من قابلية إعادة استعمال الحلية بعد فكها. لا تعتمد على قصاصات مختلطة مجهولة الهوية وحدها. اتفق على بديل الملحق الناقص قبل التركيب، ولا تخزن مواد تنظيف أو رتوش إلا إذا كانت معتمدة وضمن مدة صلاحيتها.'],
['سلم الاحتياطي إلى المالك مع سجل واضح','ضع على كل حزمة المرجع والدفعة إن توفرت والكمية والطول ومكان التركيب. اتبع تعليمات التخزين واحمها من الضرر والتعرض غير المناسب. قدم صوراً وقائمة مخزون بلغة يفهمها فريق الصيانة، مع مراجعة عربية محلية عند الحاجة. سجل القطع المصروفة بعد الإصلاح. اربط الطلب اللاحق بالمواصفة والعينة المحفوظة، لا باسم لون متداول فقط.']
],checklist:['فصل الصافي والقص واحتياطي الصيانة','طريقة استبدال مجربة للنظام المختار','قائمة أكواد الألواح والحليات والمثبتات','مسؤول محدد وسجل مخزون الصيانة'],faq:[['هل تكفي نسبة عشرة بالمئة دائماً؟','لا. تحدد هندسة الجدار وأطوال القطع وطريقة الوصول كمية الاحتياطي المناسبة.'],['هل تجعل قطع الغيار اللوح الداخلي مناسباً للخارج؟','لا. لا تغير الاستخدام المعتمد ولا تثبت مقاومة الطقس أو الحريق أو الصدمات.']],closing:'أرسل إلى Luvie مخططات الجدران ومقطع WPC وطريقة الإصلاح المقترحة. استفسر عن توفر ألواح وملحقات لاحتياطي صيانة مستقل.'}
},
{
file:'uzbekistan-pu-stone-panels-showroom-branch-handover.html',image:'uzbekistan-pu-branches-20261021.webp',product:'/products/pu-stone-panels.html',catalog:'/assets/catalogs/pu-stone-panel-catalog-en.pdf',source:'https://www.trade.gov/country-commercial-guides/uzbekistan-distribution-sales-channels',sourceName:'International Trade Administration: Uzbekistan distribution channels',related:['wall-panel-golden-sample-approval.html','uae-pu-stone-wall-panel-sample-selection.html'],
en:{title:'Uzbekistan PU Panels: Showroom Branch Handover | Luvie',heading:'PU stone panels in Uzbekistan: keep showroom branches selling the same specification',description:'Coordinate PU stone panel samples across Uzbek showroom branches with one reference register, controlled sample kits and clear order handover records.',lead:'A distributor showing PU stone-look panels in Tashkent and a second Uzbek city needs more than two attractive sample boards. If each branch uses a different name for the same finish, sales staff can send an ambiguous order to the warehouse. This guide explains how to keep display samples, quotations and replenishment requests connected. It is a proposed operating method, not a claim about existing Luvie dealers in Uzbekistan.',answer:'Use one master product register and give every branch a traceable sample kit. Connect display labels, quotations and warehouse picking to the same reference and revision. Withdraw superseded samples rather than leaving staff to infer whether they remain orderable.',sections:[
['Define the central register before splitting kits','Record supplier reference, local sales name, finish, panel dimensions, usable coverage when confirmed, matching corner reference and sample approval date. Assign responsibility for updates to one person. The ITA guide describes several distribution models in Uzbekistan and emphasizes local market knowledge; it does not endorse this particular procedure. Choose whether branches place orders centrally or directly, then make that decision visible in the register.'],
['Give each branch comparable evidence','Prepare kits from the approved selection, preserving sample identifiers and any stated variation limits. Include a view of the full repeating pattern, not only a tiny attractive fragment. A Tashkent showroom and a Samarkand branch may have different lighting, so retain the same reference photographs and explain that screens are not color standards. Have each branch acknowledge which physical sample revision it received and which old kit was removed.'],
['Make the quotation carry the warehouse reference','The customer-facing name can be localized, but the quotation must also carry the unchanged product code and approved version. Ask the local team which Uzbek or Russian terminology its buyers use; this website’s four languages do not substitute for that review. Record panel quantity, matching corners, delivery branch and unresolved technical questions separately. Do not let a display name imply exterior suitability or a certification that has not been confirmed.'],
['Control changes after the first shipment','When a finish or profile changes, freeze the affected reference for review rather than quietly substituting a new sample. Compare updated documentation and physical material, update the register and tell every branch when the change becomes orderable. Keep a record of open quotations using the old version. At receiving, reconcile carton identifiers with the branch order, investigate mismatches and avoid mixing unidentified leftovers into showroom kits.']
],checklist:['Master reference register and named owner','Traceable sample kits and branch acknowledgments','Quotation codes matching warehouse picking','Change process for samples and open quotations'],faq:[['Can each branch invent its own finish name?','A local display name is possible if it is always mapped to the same controlled supplier reference.'],['Does one sample guarantee every panel will look identical?','No. Ask for the product’s agreed appearance range and inspect the actual shipment against the approved reference.']],closing:'Send Luvie your PU reference shortlist, number of showroom locations and sample-kit questions. Confirm current specifications and sample availability before distributing branch displays.'},
es:{title:'Uzbekistán: paneles PU entre salas de exposición | Luvie',heading:'Paneles PU piedra en Uzbekistán: coordinar referencias entre sucursales',description:'Conecte muestras de paneles PU, cotizaciones y almacén entre sucursales uzbekas mediante un registro maestro, kits identificados y control de cambios.',lead:'Un distribuidor con muestras PU en Taskent y otra ciudad uzbeka necesita más que dos expositores atractivos. Si cada sucursal usa nombres distintos, el almacén puede recibir un pedido ambiguo. Esta guía conecta muestras, ofertas y reposiciones. Es una propuesta operativa, no una afirmación sobre distribuidores existentes de Luvie.',answer:'Utilice un registro maestro y kits trazables por sucursal. Etiquetas, cotizaciones y preparación de pedidos deben remitir a la misma referencia y revisión. Retire muestras antiguas en vez de dejar que el vendedor adivine si siguen disponibles.',sections:[
['Defina el registro central','Incluya referencia del proveedor, nombre local, acabado, dimensiones, cobertura confirmada, esquina compatible y fecha de aprobación. Asigne un responsable de cambios. La guía ITA describe modelos de distribución en Uzbekistán y la importancia del conocimiento local; no avala este procedimiento concreto. Decida si las sucursales compran centralmente o de forma directa y refleje esa decisión.'],
['Entregue evidencia comparable','Prepare kits de la selección aprobada, con identificadores y límites de variación acordados. Muestre el patrón completo, no solo un pequeño fragmento atractivo. Taskent y Samarcanda pueden tener iluminación distinta: conserve fotografías de referencia comunes y explique que una pantalla no es patrón de color. Cada sucursal debe confirmar la revisión recibida y la retirada del kit anterior.'],
['Lleve la referencia del almacén a la cotización','Puede traducir el nombre comercial, pero mantenga código y versión aprobada en la oferta. Pregunte al equipo local qué términos uzbekos o rusos utilizan sus compradores; las cuatro lenguas del sitio no sustituyen esa revisión. Separe cantidades, esquinas, sucursal de entrega y dudas técnicas. Un nombre de exposición no debe implicar uso exterior ni certificaciones sin verificar.'],
['Controle los cambios posteriores','Si cambia acabado o perfil, suspenda temporalmente la referencia afectada para revisión, sin sustituir muestras silenciosamente. Compare documentos y material, actualice el registro e informe cuándo puede pedirse la nueva versión. Identifique ofertas abiertas de la versión anterior. Al recibir, coteje códigos de cajas y pedido de sucursal, investigue diferencias y evite incorporar sobrantes no identificados a los kits.']
],checklist:['Registro maestro y responsable','Kits trazables y confirmación de sucursales','Códigos coherentes entre oferta y almacén','Proceso de cambios y ofertas abiertas'],faq:[['¿Puede cada tienda usar su propio nombre?','Sí, si el nombre local siempre se vincula a la referencia controlada del proveedor.'],['¿Una muestra garantiza piezas idénticas?','No. Acuerde el rango de aspecto e inspeccione el envío contra la referencia aprobada.']],closing:'Envíe a Luvie referencias PU candidatas, número de locales y dudas sobre kits. Confirme especificaciones y disponibilidad antes de repartir expositores.'},
'pt-br':{title:'Uzbequistão: painéis PU e mostruários nas filiais | Luvie',heading:'Painéis PU no Uzbequistão: alinhe as referências dos mostruários',description:'Mantenha amostras, cotações e separação de painéis PU coerentes entre filiais uzbeques com cadastro mestre, kits rastreáveis e controle de mudanças.',lead:'Um distribuidor com amostras de pedra PU em Tashkent e outra cidade uzbeque precisa de mais que dois expositores atraentes. Se cada filial usa um nome diferente, o depósito pode receber um pedido ambíguo. Este guia conecta amostras, cotações e reposições. É um método proposto, não uma afirmação sobre revendedores existentes da Luvie.',answer:'Use um cadastro mestre e forneça kits rastreáveis às filiais. Etiquetas, cotações e separação devem apontar para a mesma referência e revisão. Retire amostras superadas em vez de deixar vendedores adivinharem sua disponibilidade.',sections:[
['Defina o cadastro central','Registre código do fornecedor, nome local, acabamento, dimensões, cobertura confirmada, canto correspondente e data de aprovação. Nomeie um responsável pelas atualizações. O guia ITA descreve modelos de distribuição no Uzbequistão e a importância do conhecimento local; não aprova este procedimento específico. Decida se as filiais compram por uma central ou diretamente e documente a escolha.'],
['Entregue referências comparáveis','Monte kits da seleção aprovada, mantendo identificação e limites de variação acordados. Inclua o padrão completo, não apenas um pequeno fragmento bonito. Showrooms em Tashkent e Samarcanda podem ter luz diferente: mantenha fotos comuns e explique que telas não são padrões de cor. Cada filial deve confirmar a revisão física recebida e a retirada do kit antigo.'],
['Inclua o código do depósito na cotação','O nome comercial pode ser localizado, mas preserve código e versão aprovada na proposta. Pergunte à equipe quais termos uzbeques ou russos seus compradores usam; os quatro idiomas do site não substituem essa revisão. Separe quantidade, cantos, filial de entrega e dúvidas técnicas. Um nome no expositor não deve sugerir aplicação externa ou certificação não comprovada.'],
['Controle mudanças após a primeira entrega','Se acabamento ou perfil mudar, bloqueie a referência afetada para análise em vez de substituir amostras discretamente. Compare documentos e material físico, atualize o cadastro e avise quando a nova versão estiver disponível para pedido. Registre propostas abertas da versão anterior. No recebimento, confira caixas e pedido da filial, investigue divergências e não misture sobras sem identificação aos kits.']
],checklist:['Cadastro mestre e responsável','Kits rastreáveis e confirmações das filiais','Códigos iguais na cotação e separação','Controle de alterações e propostas abertas'],faq:[['Cada filial pode criar um nome comercial?','Pode, desde que esteja sempre ligado à mesma referência controlada do fornecedor.'],['Uma amostra garante aparência idêntica em todas as peças?','Não. Combine a faixa de aparência e confira a remessa contra a referência aprovada.']],closing:'Envie à Luvie as referências PU pretendidas, o número de showrooms e as dúvidas sobre kits. Confirme especificações e disponibilidade antes de distribuir os expositores.'},
ar:{title:'أوزبكستان: توحيد عينات ألواح PU بين الفروع | Luvie',heading:'ألواح الحجر PU في أوزبكستان: توحيد المواصفات بين فروع المعرض',description:'اربط عينات ألواح PU بعروض الأسعار والمخزون في فروع أوزبكستان، باستخدام سجل موحد ومجموعات عينات قابلة للتتبع وإجراء واضح للتغييرات.',lead:'يحتاج موزع يعرض ألواح الحجر الصناعي PU في طشقند ومدينة أوزبكية أخرى إلى أكثر من لوحتي عرض جميلتين. اختلاف أسماء التشطيب بين الفروع قد يرسل طلباً غامضاً إلى المستودع. يشرح هذا الدليل ربط العينات والعروض وطلبات التوريد. وهو طريقة عمل مقترحة، وليس وصفاً لوكلاء Luvie موجودين في أوزبكستان.',answer:'استخدم سجل منتجات رئيسياً ومجموعة عينات قابلة للتتبع لكل فرع. اربط الملصقات والعروض وتجهيز المستودع بالمرجع والإصدار نفسيهما، واسحب العينات القديمة بدلاً من ترك الموظف يخمن إمكانية طلبها.',sections:[
['حدد السجل المركزي أولاً','سجل مرجع المورد والاسم المحلي والتشطيب والأبعاد والتغطية المؤكدة ومرجع الزاوية وتاريخ اعتماد العينة. عين مسؤولاً للتحديث. يعرض دليل ITA نماذج توزيع في أوزبكستان وأهمية المعرفة المحلية، ولا يعتمد هذا الإجراء بعينه. حدد ما إذا كانت الفروع تطلب مركزياً أو مباشرة، ووضح ذلك في السجل.'],
['زود الفروع بأدلة قابلة للمقارنة','جهز المجموعات من الاختيار المعتمد مع معرفات العينات وحدود الاختلاف المتفق عليها. أظهر النمط الكامل لا جزءاً صغيراً جذاباً فقط. قد تختلف إضاءة طشقند وسمرقند، لذا احتفظ بصور مرجعية موحدة ووضح أن الشاشة ليست معيار لون. يجب أن يؤكد كل فرع إصدار العينة المستلم والمجموعة القديمة التي سحبها.'],
['انقل مرجع المستودع إلى عرض السعر','يمكن ترجمة الاسم التجاري، لكن احتفظ بكود المنتج والإصدار المعتمد في العرض. اسأل الفريق المحلي عن المصطلحات الأوزبكية أو الروسية المستخدمة؛ لغات الموقع الأربع لا تغني عن هذه المراجعة. افصل كمية الألواح والزوايا وفرع التسليم والأسئلة الفنية. لا تجعل اسم العرض يوحي بملاءمة خارجية أو شهادة غير مؤكدة.'],
['اضبط التغييرات بعد الشحنة الأولى','إذا تغير التشطيب أو المقطع، أوقف المرجع المعني للمراجعة بدلاً من تبديل العينة دون إشعار. قارن المستندات والمادة الفعلية وحدّث السجل وأبلغ الفروع بموعد إتاحة الإصدار الجديد للطلب. احتفظ بقائمة العروض المفتوحة للإصدار السابق. طابق أكواد الصناديق مع طلب الفرع عند الاستلام وحقق في الاختلافات، ولا تخلط بقايا مجهولة الهوية بمجموعات المعرض.']
],checklist:['سجل رئيسي ومسؤول محدد','عينات قابلة للتتبع وتأكيد استلام الفروع','أكواد موحدة للعروض وتجهيز المستودع','إجراء تغييرات يشمل العروض المفتوحة'],faq:[['هل يمكن لكل فرع اختيار اسم تشطيب مختلف؟','يمكن استخدام اسم محلي إذا ارتبط دائماً بالمرجع المضبوط نفسه لدى المورد.'],['هل تضمن عينة واحدة تطابق كل الألواح؟','لا. اتفق على نطاق المظهر وافحص الشحنة مقابل المرجع المعتمد.']],closing:'أرسل إلى Luvie مراجع PU المرشحة وعدد المعارض وأسئلة مجموعات العينات. تحقق من المواصفات وتوفر العينات قبل توزيعها على الفروع.'}
}
];
